<?php
declare(strict_types=1);require_once __DIR__.'/config/purchase_step14.php';$error=null;$m=['suppliers'=>0,'po_open'=>0,'bills'=>0,'pending_receipts'=>0,'outstanding'=>0.0,'overdue'=>0,'paid'=>0.0,'returns'=>0.0,'receipts'=>0];$due=[];
try{$pdo=business_db();purchase_step14_ensure($pdo);$ctx=purchase_step14_context($pdo);$orgId=(int)$ctx['organization_id'];purchase_step14_source($pdo,$orgId);$s=$pdo->prepare("SELECT COUNT(*) FROM purchase_suppliers WHERE organization_id=? AND status='active'");$s->execute([$orgId]);$m['suppliers']=(int)$s->fetchColumn();$s=$pdo->prepare("SELECT COUNT(*) FROM purchase_orders WHERE organization_id=? AND status IN ('draft','ordered')");$s->execute([$orgId]);$m['po_open']=(int)$s->fetchColumn();foreach(purchase_step14_bill_rows($pdo,$orgId,'active') as $b){$st=purchase_step14_recalc_bill($pdo,$orgId,(int)$b['id']);$m['bills']++;$m['outstanding']+=$st['outstanding'];$m['paid']+=$st['paid'];$m['returns']+=$st['return_credit'];if($b['receipt_status']!=='received')$m['pending_receipts']++;if($st['outstanding']>0.009&&$b['due_date']&&$b['due_date']<date('Y-m-d')){$m['overdue']++;$due[]=$b;}}$s=$pdo->prepare("SELECT COUNT(*) FROM purchase_receipts WHERE organization_id=? AND status='posted'");$s->execute([$orgId]);$m['receipts']=(int)$s->fetchColumn();}catch(Throwable $e){$error=$e->getMessage();}
function pc_h(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}function pc_m(mixed $v):string{return '₹'.number_format((float)$v,2,'.',',');}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Purchase Center - Healthcare Wellness Club</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/step10.css"><link rel="stylesheet" href="assets/product_pro.css"></head><body><header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="index.php"><img src="../img/logo.png" alt="logo"><span><strong>Healthcare Wellness Club</strong><small>Business OS • STEP 14 Purchase & Supplier</small></span></a><div class="os-top-actions"><a class="os-btn" href="supplier_center.php">Suppliers</a><a class="os-btn" href="purchase_receipts.php">Receipts</a><a class="os-btn primary" href="index.php">Dashboard</a></div></div></header><div class="os-layout"><aside class="os-sidebar"><div class="os-nav-label">Purchases</div><nav class="os-nav"><a class="active" href="purchase_center.php"><i class="dot"></i>Purchase Center</a><a href="supplier_center.php"><i class="dot"></i>Suppliers</a><a href="purchase_orders.php"><i class="dot"></i>Purchase Orders</a><a href="purchase_bills.php"><i class="dot"></i>Bills / Invoices</a><a href="purchase_receipts.php"><i class="dot"></i>Receipts</a><a href="supplier_payments.php"><i class="dot"></i>Payables</a><a href="purchase_returns.php"><i class="dot"></i>Returns</a><a href="purchase_analytics.php"><i class="dot"></i>Analytics</a><a href="purchase_export.php"><i class="dot"></i>Export</a><a href="step14_audit.php"><i class="dot"></i>STEP 14 Audit</a></nav></aside><main class="os-main"><section class="os-hero s10-hero"><div class="os-kicker">STEP 14 • PURCHASE COMMAND CENTER</div><h1>Supplier → PO → Bill → Receipt → Payable → Return, all in one traceable flow.</h1><p>Commitment, liability, inventory and payment are intentionally separate events so one action cannot silently double-count stock or money.</p><div class="os-status-row"><span class="os-chip <?= $error===null?'good':'' ?>"><?= $error===null?'PURCHASE SYSTEM LIVE':'Review required' ?></span><span class="os-chip"><?= $m['suppliers'] ?> active suppliers</span><span class="os-chip"><?= $m['pending_receipts'] ?> pending receipts</span><span class="os-chip"><?= $m['overdue'] ?> overdue bills</span></div></section><?php if($error):?><div class="pp-alert bad"><strong>Purchase diagnostic:</strong> <?= pc_h($error) ?></div><?php endif;?><section class="s10-kpis"><div class="s10-kpi"><small>Open POs</small><strong><?= number_format($m['po_open']) ?></strong><span>Draft / ordered commitments</span></div><div class="s10-kpi"><small>Outstanding</small><strong><?= pc_m($m['outstanding']) ?></strong><span><?= pc_m($m['paid']) ?> paid</span></div><div class="s10-kpi"><small>Return Credits</small><strong><?= pc_m($m['returns']) ?></strong><span>Supplier credits</span></div><div class="s10-kpi"><small>Goods Receipts</small><strong><?= number_format($m['receipts']) ?></strong><span>Posted to Inventory</span></div></section><section class="s10-grid"><article class="s10-card s10-span-8"><div class="os-title-row"><div><h2>STEP 14 Workflow</h2><p>Each stage has one clear business effect.</p></div><a class="os-btn primary" href="purchase_orders.php">Start Purchase</a></div><div class="os-report-grid"><a class="os-report" href="supplier_center.php"><div class="os-report-head"><b>1. Supplier</b><em>ID</em></div><span>Exact supplier identity and terms.</span><small>Open →</small></a><a class="os-report" href="purchase_orders.php"><div class="os-report-head"><b>2. Purchase Order</b><em>PLAN</em></div><span>Commitment only; no stock/payable.</span><small>PO →</small></a><a class="os-report" href="purchase_bills.php"><div class="os-report-head"><b>3. Supplier Bill</b><em>LIABILITY</em></div><span>Actual invoice and payable basis.</span><small>Bill →</small></a><a class="os-report" href="purchase_receipts.php"><div class="os-report-head"><b>4. Goods Receipt</b><em>STOCK</em></div><span>Batch/expiry inventory inward.</span><small>Receive →</small></a><a class="os-report" href="supplier_payments.php"><div class="os-report-head"><b>5. Payment</b><em>MONEY</em></div><span>Supplier collection settlement.</span><small>Pay →</small></a><a class="os-report" href="purchase_returns.php"><div class="os-report-head"><b>6. Return</b><em>CREDIT</em></div><span>Batch stock out + payable credit.</span><small>Return →</small></a></div></article><aside class="s10-card s10-span-4"><h2>Action Queue</h2><div class="s10-list"><div class="s10-row"><div><b>Pending Receipt</b><small>Bills not fully received</small></div><strong><?= number_format($m['pending_receipts']) ?></strong></div><div class="s10-row"><div><b>Overdue Bills</b><small>Outstanding past due date</small></div><strong><?= number_format($m['overdue']) ?></strong></div><div class="s10-row"><div><b>Supplier Outstanding</b><small>After returns and payments</small></div><strong><?= pc_m($m['outstanding']) ?></strong></div></div></aside><article class="s10-card s10-span-7"><h2>Management</h2><div class="os-links"><a class="os-link" href="purchase_analytics.php"><div><b>Purchase Analytics</b><span>Supplier spend, receipts, returns and overdue exposure</span></div><span>→</span></a><a class="os-link" href="purchase_export.php"><div><b>Purchase Export</b><span>CSV + Print / Save PDF</span></div><span>→</span></a><a class="os-link" href="inventory_center.php"><div><b>Inventory</b><span>Received purchase stock and batch valuation</span></div><span>→</span></a><a class="os-link" href="step14_audit.php"><div><b>STEP 14 Audit</b><span>Financial, receipt and inventory-link integrity</span></div><span>→</span></a></div></article><aside class="s10-card s10-span-5"><h2>Overdue Snapshot</h2><div class="s10-list"><?php foreach(array_slice($due,0,6) as $b):?><div class="s10-row"><div><b><?= pc_h($b['supplier_name']) ?></b><small><?= pc_h($b['invoice_number'].' • Due '.$b['due_date']) ?></small></div><strong><?= pc_m($b['outstanding']) ?></strong></div><?php endforeach;?><?php if(!$due):?><div class="s10-row"><div><b>No overdue supplier bills</b><small>Nothing needs attention here.</small></div></div><?php endif;?></div></aside></section><div class="os-footer-note"><strong>Accounting separation:</strong> PO = commitment, Bill = supplier liability, Receipt = inventory, Payment = settlement, Return = inventory out + supplier credit.</div></main></div><script src="assets/business-collapsible.js?v=20260820-1" defer></script></body></html>
